const input = $('Execute Workflow Trigger').first().json;
const companies = input.companies;
const filter = companies
  .map(c => `customerNumber eq '${String(c.properties?.erp_account_number || '').replace(/'/g, "''")}'`)
  .join(' or ');
return [{ json: { invoiceFilter: filter, companies: companies } }];

const companies = $('Build Invoice Filter').first().json.companies;
const erpNumbers = companies
  .map(c => String(c.properties?.erp_account_number || '').trim())
  .filter(Boolean);

return [{
  json: {
    filterGroups: [{
      filters: [
        { propertyName: 'dealstage',          operator: 'EQ',  value: 'closedwon' },
        { propertyName: 'erp_account_number', operator: 'IN',  values: erpNumbers }
      ]
    }],
    properties: ['erp_account_number', 'closedate'],
    limit: 200
  }
}];

const invData   = $('Fetch Invoices for Batch').first().json.value || [];
const ytdData   = $('Fetch YTD Invoices').first().json.value || [];
const dealsData = $('Fetch Won Deals').first().json.results || [];
const currentBatch = $('Build Invoice Filter').first().json.companies;

const DAY = 24 * 60 * 60 * 1000;
const today = new Date();
today.setUTCHours(0, 0, 0, 0);
const todayMs  = today.getTime();
const cutoffMs = new Date('2026-01-01T00:00:00Z').getTime();

// Last-invoice map (desc from BC)
const byCustomer = {};
for (const inv of invData) {
  const cust = String(inv.customerNumber || '');
  if (!byCustomer[cust]) byCustomer[cust] = [];
  byCustomer[cust].push(inv);
}

// YTD totals
const ytdByCustomer = {};
for (const inv of ytdData) {
  const cust = String(inv.customerNumber || '');
  ytdByCustomer[cust] = (ytdByCustomer[cust] || 0) + (Number(inv.totalAmountIncludingTax) || 0);
}

// Most-recent Closed Won deal close date per ERP (only those >= 2026-01-01)
const wonDealByErp = {};
for (const deal of dealsData) {
  const erp     = String(deal.properties?.erp_account_number || '').trim();
  const closeMs = deal.properties?.closedate
    ? new Date(deal.properties.closedate).getTime() : null;
  if (!erp || !closeMs || closeMs < cutoffMs) continue;
  if (!wonDealByErp[erp] || closeMs > wonDealByErp[erp]) wonDealByErp[erp] = closeMs;
}

const toUpdate = [];
for (const hsCompany of currentBatch) {
  const erpNum         = String(hsCompany.properties?.erp_account_number || '').trim();
  const hsId           = hsCompany.id;
  const previousStatus = hsCompany.properties?.ordering_status || null;
  if (!erpNum || !hsId) continue;

  const ytdSales = Math.round((ytdByCustomer[erpNum] || 0) * 100) / 100;

  // ── First Invoice Date ──
  const currentFirstInvMs = hsCompany.properties?.first_invoice_date
    ? Number(hsCompany.properties.first_invoice_date) : null;
  const wonDealCloseMs = wonDealByErp[erpNum] || null;

  let firstInvoiceDateMs = null;
  const shouldUpdate = wonDealCloseMs !== null
    && (currentFirstInvMs === null || wonDealCloseMs > currentFirstInvMs);

  if (shouldUpdate) {
    const afterDeal = (byCustomer[erpNum] || [])
      .filter(i => new Date(i.postingDate + 'T00:00:00Z').getTime() >= wonDealCloseMs)
      .sort((a, b) => new Date(a.postingDate) - new Date(b.postingDate));
    if (afterDeal.length > 0) {
      firstInvoiceDateMs = new Date(afterDeal[0].postingDate + 'T00:00:00Z').getTime();
    }
  }

  // ── Ordering Status ──
  const invList = (byCustomer[erpNum] || []).slice(0, 10);
  if (invList.length === 0) {
    const props = { ordering_status: 'Not Ordered', actual_sales_ytd: ytdSales };
    if ('Not Ordered' !== previousStatus) props.ordering_status_date_changed = null;
    if (firstInvoiceDateMs !== null) props.first_invoice_date = firstInvoiceDateMs;
    toUpdate.push({ id: hsId, properties: props });
    continue;
  }

  const lastInvoiceDateMs = new Date(invList[0].postingDate + 'T00:00:00Z').getTime();

  // Single invoice: treat it as both first and last invoice
  if (invList.length === 1 && firstInvoiceDateMs === null) {
    firstInvoiceDateMs = lastInvoiceDateMs;
  }

  const avgOrderSize = Math.round(
    (invList.reduce((s, i) => s + (Number(i.totalAmountIncludingTax) || 0), 0) / invList.length) * 100
  ) / 100;

  let avgDaysBetweenOrders = null;
  const sortedAsc = [...invList].sort((a, b) => new Date(a.postingDate) - new Date(b.postingDate));
  if (sortedAsc.length >= 2) {
    const gaps = [];
    for (let i = 1; i < sortedAsc.length; i++) {
      gaps.push((new Date(sortedAsc[i].postingDate) - new Date(sortedAsc[i-1].postingDate)) / DAY);
    }
    avgDaysBetweenOrders = Math.round((gaps.reduce((s, g) => s + g, 0) / gaps.length) * 10) / 10;
  }

  let riskDayMs, lostDayMs;
  if (avgDaysBetweenOrders !== null) {
    const riskDays = Math.max(Math.round(avgDaysBetweenOrders * 2), 5);
    const lostDays = Math.max(Math.round(avgDaysBetweenOrders * 3), 7);
    riskDayMs = lastInvoiceDateMs + riskDays * DAY;
    lostDayMs = lastInvoiceDateMs + lostDays * DAY;
  } else {
    riskDayMs = lastInvoiceDateMs + 14 * DAY;
    lostDayMs = lastInvoiceDateMs + 28 * DAY;
  }

  let orderingStatus;
  if      (todayMs >= lostDayMs) orderingStatus = 'Potentially Lost';
  else if (todayMs >= riskDayMs) orderingStatus = 'Outside Ordering Pattern';
  else                            orderingStatus = 'Actively Ordering';

  let statusDateMs;
  if      (orderingStatus === 'Potentially Lost')         statusDateMs = lostDayMs;
  else if (orderingStatus === 'Outside Ordering Pattern') statusDateMs = riskDayMs;
  else                                                    statusDateMs = lastInvoiceDateMs;

  const props = {
    last_invoice_date: lastInvoiceDateMs,
    avg_order_size:    avgOrderSize,
    ordering_status:   orderingStatus,
    actual_sales_ytd:  ytdSales
  };
  if (avgDaysBetweenOrders !== null) props.avg_days_between_orders = avgDaysBetweenOrders;
  if (orderingStatus !== previousStatus) props.ordering_status_date_changed = statusDateMs;
  if (firstInvoiceDateMs !== null) props.first_invoice_date = firstInvoiceDateMs;

  toUpdate.push({ id: hsId, properties: props });
}

return [{ json: { toUpdate, updateCount: toUpdate.length } }];

